import React from 'react';
import './ChatMessage.css';

const ChatMessage = ({ sender, text }) => {
  const isUser = sender === 'user';
  return (
    <div className={`message-row ${isUser ? 'user' : 'bot'}`}>
      <div className="message-bubble">
        {text}
      </div>
    </div>
  );
};

export default ChatMessage;
